export function diffusionFrame({left=24,step=0,temperature=1,area=1}={}){left=[8,16,24].includes(Number(left))?Number(left):24;const initial=left;temperature=Number(temperature)===2?2:1;area=Number(area)===2?2:1;step=Math.max(0,Math.min(12,Math.floor(Number(step)||0)));let lr=0,rl=0;for(let i=0;i<step;i++){const right=32-left,delta=left-right,net=Math.sign(delta)*Math.min(Math.abs(delta)/2,Math.max(1,Math.ceil(Math.abs(delta)*temperature*area/8))),swap=Math.min(left,right,temperature*area);lr=swap+Math.max(net,0);rl=swap+Math.max(-net,0);left-=net;}return{initial,left,right:32-left,lr,rl,step,temperature,area};}
export const cubeMeasures=side=>{side=Number(side);if(![1,2,4].includes(side))side=1;return{side,surface:6*side**2,volume:side**3,ratio:6/side};};
export const coreFraction=(side,depth)=>Math.max(0,Number(side)-2*Math.max(0,Number(depth)||0))**3/Number(side)**3;
export const diffusionTasks=[{id:'gradient',title:'Which way is the net movement?',left:24,answer:'right',options:[['left','Right to left'],['right','Left to right'],['none','No net movement']],why:'Equal compartments start with more particles on the left. Particles move both ways; more cross left to right overall.'},{id:'equal',title:'Equal concentration: have particles stopped?',left:16,answer:'both',options:[['stopped','All particles stop'],['both','Both ways; no net movement'],['right','Only left to right']],why:'At equal concentration particles continue moving both ways. Equal transfers give no net movement.'},{id:'reverse',title:'Reverse the gradient',left:8,answer:'left',options:[['left','Right to left'],['right','Left to right'],['none','No net movement']],why:'Now concentration is higher on the right. Net movement reverses, without particles knowing a destination.'},{id:'temperature',title:'Test temperature alone',left:24,answer:'faster',options:[['slower','Slower at higher temperature'],['faster','Faster at higher temperature'],['same','Temperature never matters']],why:'Higher temperature gives particles more kinetic energy. Compare equal starting concentrations and membrane areas.'},{id:'area',title:'Test membrane area alone',left:24,answer:'faster',options:[['same','Area never matters'],['faster','Faster with a larger area'],['reversed','Area reverses the gradient']],why:'A larger membrane area provides more space for exchange. Hold temperature and starting concentrations constant.'}];
export const exchangeCases=[
{id:'lungs',name:'Lungs',feature:'ventilation',featureName:'Fresh air ventilation',effect:'gradient',detail:'Many alveoli provide a large surface area. Thin alveolar/capillary walls shorten the path. Blood flow and ventilation maintain oxygen and carbon dioxide gradients.',off:'Without fresh air, oxygen in the air space falls as it diffuses into blood.',on:'Fresh air replenishes oxygen; blood flow carries absorbed oxygen away.'},
{id:'intestine',name:'Small intestine',feature:'area',featureName:'Villi and microvilli',effect:'area',detail:'Villi and microvilli greatly increase exchange area. A thin surface and efficient blood supply help absorption of digested substances. Some absorption uses active transport, studied later.',off:'A smooth surface has less area for exchange at the same overall size.',on:'Folds expose more surface to the gut contents.'},
{id:'gills',name:'Fish gills',feature:'blood',featureName:'Efficient blood supply',effect:'gradient',detail:'Gill filaments and lamellae provide a large area and short diffusion paths. Water passing over the gills and efficient blood flow maintain gas gradients.',off:'Oxygen can accumulate locally when blood is not carrying it away.',on:'Blood carries absorbed oxygen away, helping maintain a concentration gradient.'},
{id:'roots',name:'Plant roots',feature:'area',featureName:'Root-hair projection',effect:'area',detail:'Root hairs increase contact area with soil. Their thin walls give short paths. Water uptake by osmosis and mineral-ion uptake by active transport are studied next; neither should be called diffusion in every context.',off:'The counterfactual root cell has no hair, so less surface contacts the soil.',on:'The hair provides extra surface in contact with soil.'},
{id:'leaves',name:'Plant leaves',feature:'path',featureName:'Thin leaf and air spaces',effect:'path',detail:'A broad leaf has a large area. A thin shape, stomata and internal air spaces provide short routes for gas diffusion. Carbon dioxide can diffuse towards photosynthesising cells down its gradient.',off:'A thick solid model makes the gas path longer.',on:'A thin leaf and air spaces shorten the path to cells.'}
];
export const exchangeOptions=[['area','More exchange area'],['path','A shorter diffusion path'],['gradient','Maintains a concentration gradient'],['energy','Particles need energy from respiration']];
export const comparedStates=states=>states?.includes('on')&&states?.includes('off');
